from math import sqrt

def eta(a,b):
 if b<a:
  return 1-b/a
 if b>a:
  return 1-(1-b)/(1-a)
 return 0.
for delta in [0.001,0.01,0.05]:
 p,q=.5-delta,.5+delta
 candidates=[0.,p,q,1.]
 vals=[.5*(eta(a,p)+eta(a,q)) for a in candidates]
 print({'TV_from_fair':delta,'exact_binary_DCP':min(vals),'formula':2*delta/(1+2*delta),'optimal_baseline':candidates[vals.index(min(vals))]})

def surrogate(a,b):
 return a*a-a*b if b<a else (1-a)**2-(1-b)*(1-a) if b>a else 0.
p=(.6,.2); q=(.7,.5); mid=tuple((x+y)/2 for x,y in zip(p,q))
print({'eta_convex_endpoints':[surrogate(*p),surrogate(*q)],'midpoint':surrogate(*mid),'endpoint_average':(surrogate(*p)+surrogate(*q))/2,'hessian_eigenvalues':[1-sqrt(2),1+sqrt(2)]})
